mapper.insert:
insert ignore into p_outbox
    (id,created_at,updated_at,account_id,event_id,event_type,aggregate_type,aggregate_id,schema_version,trace_id,payload,status,attempt_count,next_run_at)
     and t.account_id=#{accountId} and t.id=#{taskId}

mapper.update:
update p_webhook_attempt set finished_at=utc_timestamp(3),
    error_code='LEASE_EXPIRED',updated_at=utc_timestamp(3) where delivery_id=#{deliveryId}
    and attempt_no=#{attemptNo} and finished_at is null

mapper.select:
select id as deliveryId,endpoint_id as endpointId,event_id as eventId,
    task_id as taskId,event_type as eventType,status,attempt_count as attemptCount,last_http_status as lastHttpStatus,
    last_error_code as lastErrorCode,next_attempt_at as nextAttemptAt,delivered_at as deliveredAt,created_at as createdAt
    from p_webhook_delivery where account_id=#{accountId} and endpoint_id=#{endpointId}
    and created_at >= #{from}
    and created_at < date_add(#{to},interval 1 day)
    order by created_at desc,id desc limit #{limit} offset #{offset}

select count(*) from p_webhook_delivery
    where account_id=#{accountId} and endpoint_id=#{endpointId}
    and created_at >= #{from}
    and created_at < date_add(#{to},interval 1 day)

select a.id as attemptId,a.attempt_no as attemptNo,
    a.http_status as httpStatus,a.error_code as errorCode,a.latency_ms as latencyMs,
    a.started_at as startedAt,a.finished_at as finishedAt from p_webhook_attempt a
    join p_webhook_delivery d on d.id=a.delivery_id and d.account_id=a.account_id
    where a.account_id=#{accountId} and a.delivery_id=#{deliveryId}
    and a.created_at >= #{from}
    and a.created_at < date_add(#{to},interval 1 day)
    order by a.attempt_no desc limit #{limit} offset #{offset}

select count(*) from p_webhook_attempt a
    join p_webhook_delivery d on d.id=a.delivery_id and d.account_id=a.account_id
    where a.account_id=#{accountId} and a.delivery_id=#{deliveryId}
    and a.created_at >= #{from}
    and a.created_at < date_add(#{to},interval 1 day)
